using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using LittleLeo;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "ActionsQueueState", menuName = "Data/Battle/Game States/ActionsQueue State")]
public class ActionsQueueState : GameState
{
	[Header("Assets")]
	[SerializeField]
	private CorruptionSourcePurgedHandler corruptionSourcePurgedHandler;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private GameObjectReference runesPanelGameObjectReference;

	[Header("Events")]
	[SerializeField]
	private VoidEvent OnActionsOnQueueEnded;

	[Header("Debug")]
	[SerializeField]
	private bool verbose;

	[NonSerialized]
	private List<IEnumerator> onBeforeAllActionsCoroutines = new List<IEnumerator>();

	[NonSerialized]
	private List<IEnumerator> companionAndEnemyDefeatSetupCoroutines = new List<IEnumerator>();

	[NonSerialized]
	private List<IEnumerator> companionAndEnemyDefeatAnimationCoroutines = new List<IEnumerator>();

	[NonSerialized]
	private List<IEnumerator> companionAndEnemyDefeatActionsCoroutines = new List<IEnumerator>();

	[NonSerialized]
	private List<IEnumerator> astreaBallCoroutines = new List<IEnumerator>();

	[NonSerialized]
	private IEnumerator astreaFirstPhaseDefeatedCoroutine;

	[NonSerialized]
	private List<IEnumerator> enemyLeavingAnimationCoroutines = new List<IEnumerator>();

	[NonSerialized]
	private List<IEnumerator> playerLoseHeartCoroutine = new List<IEnumerator>();

	[NonSerialized]
	private List<IEnumerator> startOfTurnActionsCoroutines = new List<IEnumerator>();

	[NonSerialized]
	private List<IEnumerator> nefariousPulseDischargeRuinActionsCoroutines = new List<IEnumerator>();

	[NonSerialized]
	private IEnumerator aphoticInstinctAction;

	[NonSerialized]
	private List<IEnumerator> afflictionReliefHealbotActionsCoroutines = new List<IEnumerator>();

	[NonSerialized]
	private List<IEnumerator> beforeMainActionsCoroutine = new List<IEnumerator>();

	[NonSerialized]
	private List<IEnumerator> mainActionsCoroutines = new List<IEnumerator>();

	[NonSerialized]
	private IEnumerator afterCrimsomEquinoxDiceActivationActionCoroutine;

	[NonSerialized]
	private List<IEnumerator> afterMainActionsCoroutines = new List<IEnumerator>();

	[NonSerialized]
	private List<IEnumerator> afterAfterMainActionsCoroutines = new List<IEnumerator>();

	[NonSerialized]
	private IEnumerator evilSoulHeatActionCoroutine;

	[NonSerialized]
	private IEnumerator calmActionCoroutine;

	[NonSerialized]
	private bool actionsQueueExecuting;

	[NonSerialized]
	public bool CorruptionSourcePurged;

	[NonSerialized]
	public bool DisableEnqueueNormalPurifyCorruptCoroutineAction;

	[NonSerialized]
	private int linkedActionsEndedCounter;

	[NonSerialized]
	private bool ignoreNextRunActionWaitForFramesOnMobile;

	public CurrentCorruptedAnimals CurrentCorruptedAnimals => currentCorruptedAnimals;

	public VoidEvent OnActionsOnQueueEndedRef => OnActionsOnQueueEnded;

	public void SetActionsQueueExecuting(bool value)
	{
		actionsQueueExecuting = value;
	}

	public void OnReset()
	{
		onBeforeAllActionsCoroutines.Clear();
		ResetOnDeathActions();
		ResetStartTurnActions();
		ResetMainActions();
		actionsQueueExecuting = false;
		CorruptionSourcePurged = false;
		DisableEnqueueNormalPurifyCorruptCoroutineAction = false;
		linkedActionsEndedCounter = 0;
		ignoreNextRunActionWaitForFramesOnMobile = false;
	}

	private void ResetOnDeathActions()
	{
		companionAndEnemyDefeatSetupCoroutines.Clear();
		companionAndEnemyDefeatAnimationCoroutines.Clear();
		companionAndEnemyDefeatActionsCoroutines.Clear();
		astreaBallCoroutines.Clear();
		astreaFirstPhaseDefeatedCoroutine = null;
		enemyLeavingAnimationCoroutines.Clear();
		playerLoseHeartCoroutine.Clear();
	}

	private void ResetStartTurnActions()
	{
		startOfTurnActionsCoroutines.Clear();
		aphoticInstinctAction = null;
		afflictionReliefHealbotActionsCoroutines.Clear();
		nefariousPulseDischargeRuinActionsCoroutines.Clear();
	}

	private void ResetMainActions()
	{
		beforeMainActionsCoroutine.Clear();
		mainActionsCoroutines.Clear();
		afterCrimsomEquinoxDiceActivationActionCoroutine = null;
		afterMainActionsCoroutines.Clear();
		afterAfterMainActionsCoroutines.Clear();
		evilSoulHeatActionCoroutine = null;
		calmActionCoroutine = null;
	}

	public bool IsAnyActionOnQueuesOrAnyActionsExecuting()
	{
		if (!actionsQueueExecuting && onBeforeAllActionsCoroutines.Count <= 0 && companionAndEnemyDefeatSetupCoroutines.Count <= 0 && companionAndEnemyDefeatAnimationCoroutines.Count <= 0 && companionAndEnemyDefeatActionsCoroutines.Count <= 0 && astreaBallCoroutines.Count <= 0 && astreaFirstPhaseDefeatedCoroutine == null && enemyLeavingAnimationCoroutines.Count <= 0 && playerLoseHeartCoroutine.Count <= 0 && startOfTurnActionsCoroutines.Count <= 0 && nefariousPulseDischargeRuinActionsCoroutines.Count <= 0 && aphoticInstinctAction == null && afflictionReliefHealbotActionsCoroutines.Count <= 0 && beforeMainActionsCoroutine.Count <= 0 && mainActionsCoroutines.Count <= 0 && afterCrimsomEquinoxDiceActivationActionCoroutine == null && afterMainActionsCoroutines.Count <= 0 && afterAfterMainActionsCoroutines.Count <= 0 && evilSoulHeatActionCoroutine == null)
		{
			return calmActionCoroutine != null;
		}
		return true;
	}

	public void EnqueueOnBeforeAllActionsAction(IEnumerator actionCoroutine)
	{
		onBeforeAllActionsCoroutines.Add(actionCoroutine);
	}

	public void EnqueueCompanionAndEnemyDefeatSetupCoroutines(IEnumerator actionCoroutine)
	{
		Debug.Log("EnqueueCompanionAndEnemyDefeatSetupCoroutines");
		companionAndEnemyDefeatSetupCoroutines.Add(actionCoroutine);
	}

	public void EnqueueCompanionAndEnemyDefeatAnimationCoroutines(IEnumerator actionCoroutine)
	{
		Debug.Log("EnqueueCompanionAndEnemyDefeatAnimationCoroutines");
		companionAndEnemyDefeatAnimationCoroutines.Add(actionCoroutine);
	}

	public void EnqueueCompanionAndEnemyDefeatAction(IEnumerator actionCoroutine)
	{
		companionAndEnemyDefeatActionsCoroutines.Add(actionCoroutine);
	}

	public void EnqueueAstreaBallAction(IEnumerator actionCoroutine)
	{
		Debug.Log("----- EnqueueAstreaBallAction -----");
		astreaBallCoroutines.Add(actionCoroutine);
	}

	public void SetAstreaFirstPhaseDefeatedAction(IEnumerator actionCoroutine)
	{
		if (astreaFirstPhaseDefeatedCoroutine == null)
		{
			astreaFirstPhaseDefeatedCoroutine = actionCoroutine;
		}
	}

	public void EnqueueEnemyLeavingAnimationAction(IEnumerator actionCoroutine)
	{
		enemyLeavingAnimationCoroutines.Add(actionCoroutine);
	}

	public void SetPlayerLoseHeartCoroutine(IEnumerator actionCoroutine)
	{
		playerLoseHeartCoroutine.Add(actionCoroutine);
	}

	public void EnqueueStartOfTurnAction(IEnumerator actionCoroutine)
	{
		startOfTurnActionsCoroutines.Add(actionCoroutine);
	}

	public void InsertAsNextStartOfTurnAction(IEnumerator actionCoroutine)
	{
		startOfTurnActionsCoroutines.Insert(0, actionCoroutine);
	}

	public void EnqueueNefariousPulseDischargeRuinAction(IEnumerator actionCoroutine)
	{
		nefariousPulseDischargeRuinActionsCoroutines.Add(actionCoroutine);
	}

	public void SetAphoticInstinctAction(IEnumerator actionCoroutine)
	{
		aphoticInstinctAction = actionCoroutine;
	}

	public void EnqueueAfflictionReliefHealbotForcefulStreamAction(IEnumerator actionCoroutine)
	{
		afflictionReliefHealbotActionsCoroutines.Add(actionCoroutine);
	}

	public void EnqueueBeforeMainActionAction(IEnumerator actionCoroutine)
	{
		beforeMainActionsCoroutine.Add(actionCoroutine);
	}

	public void EnqueueAction(IEnumerator actionCoroutine, bool ignoreNextRunActionWaitForFramesOnMobile = false)
	{
		mainActionsCoroutines.Add(actionCoroutine);
		"Action Enqueued".DebugLogIfVerbose(verbose);
	}

	public void SetAfterCrimsomEquinoxDiceActivationAction(IEnumerator actionCoroutine)
	{
		afterCrimsomEquinoxDiceActivationActionCoroutine = actionCoroutine;
	}

	public void EnqueueAfterAction(IEnumerator actionCoroutine)
	{
		afterMainActionsCoroutines.Add(actionCoroutine);
	}

	public void EnqueueAfterAfterAction(IEnumerator actionCoroutine)
	{
		afterAfterMainActionsCoroutines.Add(actionCoroutine);
	}

	public void SetEvilSoulHeatAction(IEnumerator actionCoroutine)
	{
		evilSoulHeatActionCoroutine = actionCoroutine;
	}

	public void SetCalmActionAction(IEnumerator actionCoroutine)
	{
		calmActionCoroutine = actionCoroutine;
	}

	public void EnqueueNormalPurifyCorruptCoroutineAction()
	{
		if (DisableEnqueueNormalPurifyCorruptCoroutineAction)
		{
			"DisableEnqueueNormalPurifyCorruptCoroutineAction".DebugLogIfVerbose(verbose);
			return;
		}
		"EnqueueNormalPurifyCorruptCoroutineAction".DebugLogIfVerbose(verbose);
		EnqueueAction(NormalPurifyCorruptCoroutine());
	}

	private IEnumerator NormalPurifyCorruptCoroutine()
	{
		Debug.Log("NormalPurifyCorruptCoroutine: Start");
		yield return new WaitForSeconds(0.08f);
		Debug.Log("NormalPurifyCorruptCoroutine: End");
	}

	public override void OnStartState()
	{
		base.OnStartState();
		if (actionsQueueExecuting)
		{
			Debug.Log("Actions Queue Already Executing");
		}
		else if (!ignoreNextRunActionWaitForFramesOnMobile)
		{
			InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 2, delegate
			{
				ReferenceSingleton<CoroutineHandler>.Instance.Run(RunActions());
			});
		}
		else
		{
			ReferenceSingleton<CoroutineHandler>.Instance.Run(RunActions());
		}
	}

	private IEnumerator RunActions()
	{
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		if (instance.CurrentState == instance.DeathState)
		{
			actionsQueueExecuting = false;
			yield break;
		}
		ReferenceSingleton<GameplayHandler>.Instance.SetTimeScaleSpeedBasedOnBattleSpeed();
		actionsQueueExecuting = true;
		CoroutineHandler coroutineHandler = ReferenceSingleton<CoroutineHandler>.Instance;
		if (!ignoreNextRunActionWaitForFramesOnMobile)
		{
			yield return InvokeAlternatives.WaitForFrames(7);
		}
		else
		{
			ignoreNextRunActionWaitForFramesOnMobile = false;
		}
		if (onBeforeAllActionsCoroutines.Count > 0)
		{
			yield return RunActionsEnqueued(onBeforeAllActionsCoroutines);
		}
		else if (companionAndEnemyDefeatSetupCoroutines.Count > 0)
		{
			RunActionsLinked(companionAndEnemyDefeatSetupCoroutines);
		}
		else if (companionAndEnemyDefeatActionsCoroutines.Count > 0)
		{
			RunActionsLinked(companionAndEnemyDefeatActionsCoroutines);
		}
		else if (companionAndEnemyDefeatAnimationCoroutines.Count > 0)
		{
			RunActionsLinked(companionAndEnemyDefeatAnimationCoroutines);
		}
		else if (astreaBallCoroutines.Count > 0)
		{
			Debug.Log("----- astreaBallCoroutines.Count > 0 -----");
			RunActionsLinked(astreaBallCoroutines);
		}
		else if (astreaFirstPhaseDefeatedCoroutine != null)
		{
			yield return coroutineHandler.Run(astreaFirstPhaseDefeatedCoroutine);
			astreaFirstPhaseDefeatedCoroutine = null;
			coroutineHandler.Run(RunActions());
		}
		else if (enemyLeavingAnimationCoroutines.Count > 0)
		{
			RunActionsLinked(enemyLeavingAnimationCoroutines);
		}
		else if (playerLoseHeartCoroutine.Count > 0 && ReferenceSingleton<GameStateManager>.Instance.EndPlayerTurnState.EndTurnActivations.Count == 0 && ReferenceSingleton<GameStateManager>.Instance.StartPlayerTurnState.StartTurnActivations.Count == 0)
		{
			yield return RunActionsEnqueued(playerLoseHeartCoroutine);
		}
		else if (nefariousPulseDischargeRuinActionsCoroutines.Count > 0)
		{
			RunActionsLinked(nefariousPulseDischargeRuinActionsCoroutines);
		}
		else if (startOfTurnActionsCoroutines.Count > 0)
		{
			yield return RunActionsEnqueued(startOfTurnActionsCoroutines);
		}
		else if (aphoticInstinctAction != null)
		{
			yield return coroutineHandler.Run(aphoticInstinctAction);
			aphoticInstinctAction = null;
			coroutineHandler.Run(RunActions());
		}
		else if (afflictionReliefHealbotActionsCoroutines.Count > 0)
		{
			RunActionsLinked(afflictionReliefHealbotActionsCoroutines);
		}
		else if (beforeMainActionsCoroutine.Count > 0)
		{
			yield return RunActionsEnqueued(beforeMainActionsCoroutine);
		}
		else if (mainActionsCoroutines.Count > 0)
		{
			Debug.Log("MainsActionCoroutines");
			yield return RunActionsEnqueued(mainActionsCoroutines);
		}
		else if (afterCrimsomEquinoxDiceActivationActionCoroutine != null)
		{
			yield return coroutineHandler.Run(afterCrimsomEquinoxDiceActivationActionCoroutine);
			afterCrimsomEquinoxDiceActivationActionCoroutine = null;
			coroutineHandler.Run(RunActions());
		}
		else if (afterMainActionsCoroutines.Count > 0)
		{
			yield return RunActionsEnqueued(afterMainActionsCoroutines);
		}
		else if (afterAfterMainActionsCoroutines.Count > 0)
		{
			yield return RunActionsEnqueued(afterAfterMainActionsCoroutines);
		}
		else if (ReferenceSingleton<DiceRollingHandler>.Instance.IsDiceRolling)
		{
			ReferenceSingleton<CoroutineHandler>.Instance.Run(RunActions());
		}
		else if (calmActionCoroutine != null)
		{
			yield return coroutineHandler.Run(calmActionCoroutine);
			calmActionCoroutine = null;
			coroutineHandler.Run(RunActions());
		}
		else if (evilSoulHeatActionCoroutine != null)
		{
			yield return coroutineHandler.Run(evilSoulHeatActionCoroutine);
			evilSoulHeatActionCoroutine = null;
			coroutineHandler.Run(RunActions());
		}
		else
		{
			EndActionQueueState();
		}
	}

	private void RunActionsLinked(List<IEnumerator> actionsList)
	{
		CoroutineHandler instance = ReferenceSingleton<CoroutineHandler>.Instance;
		List<IEnumerator> list = actionsList.Duplicate();
		actionsList.Clear();
		linkedActionsEndedCounter = list.Count;
		for (int i = 0; i < list.Count; i++)
		{
			instance.Run(RunActionLinked(list[i]));
		}
	}

	private IEnumerator RunActionLinked(IEnumerator action)
	{
		CoroutineHandler instance = ReferenceSingleton<CoroutineHandler>.Instance;
		yield return instance.Run(action);
		OnLinkedActionEnded();
	}

	private void OnLinkedActionEnded()
	{
		linkedActionsEndedCounter--;
		if (linkedActionsEndedCounter == 0)
		{
			ReferenceSingleton<CoroutineHandler>.Instance.Run(AfterLinkedActionsCoroutine());
		}
	}

	private IEnumerator AfterLinkedActionsCoroutine()
	{
		yield return InvokeAlternatives.WaitForFrames(3, tryUsingWaitForFixedUpdate: true);
		ReferenceSingleton<CoroutineHandler>.Instance.Run(RunActions());
	}

	private IEnumerator RunActionsEnqueued(List<IEnumerator> actionsList)
	{
		CoroutineHandler coroutineHandler = ReferenceSingleton<CoroutineHandler>.Instance;
		yield return coroutineHandler.Run(actionsList.PopFirst());
		coroutineHandler.Run(RunActions());
	}

	private void EndActionQueueState()
	{
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		if (instance.CurrentState != instance.DeathState)
		{
			actionsQueueExecuting = false;
			OnActionsOnQueueEnded.Raise();
			"OnActionsOnQueueEnded".DebugLogIfVerbose(verbose);
			if (CorruptionSourcePurged)
			{
				"CorruptionSourcePurged".DebugLogIfVerbose(verbose);
				corruptionSourcePurgedHandler.CorruptionSourcePurged();
			}
			if (CorruptionSourcePurged || currentCorruptedAnimals.activeCorruptedAnimals.Count == 0)
			{
				"Calling End Player Turn State".DebugLogIfVerbose(verbose);
				ReferenceSingleton<GameStateManager>.Instance.TryEnterEndPlayerTurnStateIfNotEndOfBattleStateAlreadyCalled();
			}
			else if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.EnemyTurn)
			{
				instance.SetState(instance.CorruptPlayerState);
			}
			else if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.EndOfAllTurn)
			{
				instance.SetState(instance.EndOfAllTurnState);
			}
			else if (instance.PreviouslyGameState == instance.StartPlayerTurnState || instance.PreviouslyGameState == instance.EndPlayerTurnState)
			{
				instance.SetState(instance.PreviouslyGameState);
			}
			else if (instance.CurrentState != instance.StartPlayerTurnState && instance.CurrentState != instance.EndPlayerTurnState && instance.CurrentState != instance.ChooseDiceOnPoolState && instance.CurrentState != instance.PrecisionActionState && ReferenceSingleton<TurnManager>.Instance.CurrentTurn != ReferenceSingleton<TurnManager>.Instance.DrawTurn && ReferenceSingleton<TurnManager>.Instance.CurrentTurn != null)
			{
				ReferenceSingleton<GameplayHandler>.Instance.ResetTimeScale();
				if (!ReferenceSingleton<GameStateManager>.Instance.EndOfBattleStateAlreadyCalled)
				{
					ReferenceSingleton<CoroutineHandler>.Instance.Run(WaitUntilAllDiceAreOnHandEnterChooseActionState());
				}
			}
			else if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.DrawTurn && currentCorruptedAnimals.IsAnyEnemyActive())
			{
				ReferenceSingleton<TurnManager>.Instance.StartNextTurn();
			}
		}
		CorruptionSourcePurged = false;
		DisableEnqueueNormalPurifyCorruptCoroutineAction = false;
	}

	private IEnumerator WaitUntilAllDiceAreOnHandEnterChooseActionState()
	{
		List<DiceInstance> diceHand = ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices;
		for (int i = 0; i < diceHand.Count; i++)
		{
			if (diceHand[i].DiceState == DiceState.Dragged)
			{
				diceHand[i].StopFollowingMouse();
			}
		}
		List<RuneInstance> runeInstances = runesPanelGameObjectReference.value.GetComponent<RunesPanel>().runeInstances;
		for (int j = 0; j < runeInstances.Count; j++)
		{
			if (!(runeInstances[j] == null) && runeInstances[j].Dragging)
			{
				runeInstances[j].StopFollowingMouse();
			}
		}
		yield return new WaitUntil(delegate
		{
			for (int k = 0; k < diceHand.Count; k++)
			{
				if (diceHand[k].DiceState != DiceState.OnHand)
				{
					return false;
				}
			}
			for (int l = 0; l < runeInstances.Count; l++)
			{
				if (!(runeInstances[l] == null) && runeInstances[l].Dragging)
				{
					return false;
				}
			}
			return true;
		});
		ReferenceSingleton<GameStateManager>.Instance.SetChooseActionState();
	}
}
